claims=[
 record('SINGLETON-LEFT-INVERSE','The archived actual old-stage carrier admits Diff only. u0(Diff)=Diff and d1(Diff)=Diff, while d1 of every other supplied term returns a typed receipt retaining that term. Thus the old-image left inverse is true but does not establish upper-stage admission or semantic conservativity.',[evidence('docs/source_archive/mss0_mss1_52cb5457/updown_maps.py',(1,66)),evidence('code/tests/test_008_source_bound_examples.py',(50,76))],status='full_source_review_and_fresh_offline_tests',limits='Singleton old carrier; no arbitrary MSSn tower, all-language retraction, or semantic interpretation preservation.'),
 record('INTEGER-GRAPH-CERTIFICATES','For a declared connected integer edge-difference graph, a potential satisfying every edge is a positive witness; a declared-edge closed walk with nonzero signed sum is a negative witness by telescoping. BFS propagation produces these for the fixed fixtures. An independent bounded potential search agrees on all 125 tested triangle claim triples.',[evidence('code/retraction_benchmark_runner.py',(120,254)),evidence('code/tests/test_008_source_bound_examples.py',(112,127))],status='full_source_review_algebraic_reasoning_and_bounded_fresh_tests',limits='Assumes well-formed graph and integer claims. Residual sum is a spanning-tree diagnostic, not minimal L1 repair distance; admission gaps recorded below.'),
 record('FEASIBILITY-BEFORE-GAP','The retained exact flow fixture has equal primal/dual values while failing balance. All capacity, balance, gap and price clauses must be checked; zero gap alone cannot certify the encoded problem.',[evidence('lean4/FlowCertificate.lean',(25,60),(67,114)),evidence('code/tests/test_008_source_bound_examples.py',(88,96))],status='full_Lean_source_read_with_fresh_finite_Python_reconstruction',limits='Six fixed networks and 24 decided propositions; no generic LP duality theorem or current Lean replay. Generic Net values additionally require carrier admission.'),
 record('FORWARD-DIFFERENCE-CERTIFICATE','ExactRat.Poly proves by induction that finite nonnegative starting forward differences plus an eventually constant difference imply nonnegative polynomial values for every natural n>=n0; the strict form requires a positive start. This is a substantive conditional finite-certificate-to-infinite-natural-family mechanism.',[evidence('lean4/ExactRat/Poly.lean',(184,193),(197,300)),evidence('lean4/ExactRat/Laws.lean',(1,285))],status='complete_written_Lean_proof_body_review_with_retained_historical_receipt_only',limits='Sufficient conditions for exact rational polynomials on the natural tail, not a completeness result for arbitrary real positivity. No fresh Lean kernel pass.'),
 record('SCOPED-CENSUS-GATE','The package verifier requires a nonempty expected named census, approved axioms and exact declaration/axiom-set agreement including duplicate rejection; seven mocked tests exercise these failure modes. The named 39, full 576 local declarations and external 52 payloads are different scopes.',[evidence('verify_deposit.py',(1,237)),evidence('code/tests/test_008_deposit_gates.py',(1,65)),evidence('lean4/Census.lean',(1,52)),evidence('lean4/FullCensus.lean',(1,24))],status='full_source_review_and_7_fresh_mocked_gate_tests',limits='Fresh generation-only --check passes; mocked subprocess results do not establish a kernel run, theorem adequacy or external payload verification.'),
 record('CONDITIONAL-PAIRED-ARITHMETIC','The four two-sided exact McNemar values from supplied discordant counts are 145499/4194304, 1/32, 1/2048 and 1/2^33. The 36/50 and 38/50 structured runs must remain separate.',[evidence('code/tests/test_008_source_bound_examples.py',(98,110)),evidence('docs/source_archive/c005_working_report.md',(1,35))],status='full_source_review_and_fresh_exact_fraction_tests',limits='Conditional arithmetic only: C005 per-case rows are absent, so the paired counts, causal mechanism and general model ability are not independently reconstructed.')]
findings=[
 record('CURRENT-CUSTODY-DRIFT','Current MANIFEST has 30 raw mismatches among 71 entries and SHA256SUMS has 31 among 72; 18/19 remain after LF normalization. Fresh default verification fails with 31 issues. The ZIP internal manifests have zero mismatches. Current source-example tests pass 10 and fail the archive byte/size identity assertion; the same archived suite passes all 11.',[evidence('MANIFEST.sha256'),evidence('SHA256SUMS'),evidence('code/tests/test_008_source_bound_examples.py',(36,46)),evidence('docs/source_archive/source_index.json',(1,112))],severity='custody_mismatch',recommended_action='Preserve original archive/receipts; create a separately versioned current edition and mapping before regenerating its hashes. Do not overwrite historical metadata to hide changes.'),
 record('HISTORICAL-IDENTITY-BOUNDARY','All 13 source-index archived members match exact admitted bytes; only 11 loose members do. K4 report differs by newlines; C005 also has three historical path substitutions. Current source-index origin paths are renamed without changing old revisions/blob IDs. Twelve of thirteen protected Lean source rows still match; lean-toolchain changed 4.34 to 4.35. The full axiom report matches only after LF normalization. Current translated command paths do not establish new execution.',[evidence('docs/source_archive/source_index.json',(1,112)),evidence('docs/source_archive/c005_working_report.md',(383,456)),evidence('lean4/lean-toolchain',(1,1)),evidence('docs/review_validation_2026_10_02.json',(239,282))],severity='historical_evidence_not_current_binding',recommended_action='Cite archive-original paths/hashes for historical provenance; maintain explicit current path translations separately. Future Lean replay must bind actual source, compiler and output, without rewriting retained receipts.'),
 record('GRAPH-AND-BUDGET-ADMISSION','Callable graph verifiers do not admit claim types before arithmetic. A NaN self-loop is accepted as a nonzero closed-walk witness and a Boolean edge claim is accepted by an integer potential. BudgetController.record_cost(NaN) makes a subsequent large estimated cost comparison fail open. These are out-of-declared-domain API controls, not failures of the six valid fixtures.',[evidence('code/retraction_benchmark_runner.py',(55,62),(207,239),(274,291),(316,326))],severity='reusable_api_admission_gap',recommended_action='For a new reusable adapter, validate exact integer edge types, complete declared vertex carrier and finite nonnegative budget inputs. Keep the current historical runner unchanged in this audit; JSON receipt serialization already rejects NaN, so no invalid stored receipt or actual overspend is claimed.'),
 record('FLOW-CARRIER-ADMISSION','The generic Net type permits nodes=0 with arc(0,1), weight=load=flow=[1], level=[], price=1. Defaults make primal=dual=price=1, capacity is true and balance is vacuous, so all four value clauses pass although the arc endpoints lie outside the carrier. The fixed three-node fixtures do not exhibit this defect.',[evidence('lean4/FlowCertificate.lean',(25,60))],severity='finite_counterexample_to_unqualified_checker_reuse',recommended_action='Add separate carrier/dimension admission in any new adapter before applying these predicates. This is a direct exact reduction of definitions, not a fresh Lean counterexample build.'),
 record('CATEGORY-AND-SHEAF-LABEL-LIMITS','Level22 compSub discards both inputs and returns name=comp, so composing an identity with a substitution named custom does not equal that substitution. reindex ignores the substitution. Level23 sections are total Nat functions independent of domain and BinaryCover has only inclusion inequalities; no topology, cover/intersection or general gluing existence is encoded. The proved equalities are valid in these thin encodings, while stronger label-based interpretations are unsupported.',[evidence('lean4/Level22FibredDependentContexts.lean',(19,72)),evidence('lean4/Level23SheafDescent.lean',(17,77)),evidence('lean4/Level16IndObject.lean',(1,83))],severity='mathematical_scope_boundary',recommended_action='Reuse the actual typed-retagging and equality/conflict examples under those names. Genuine categorical/fibred/sheaf transfer requires new lawful encodings and proofs; do not promote file titles into those foundations.'),
 record('HISTORICAL-MODEL-CLAIM-CEILING','The C005 working body makes architectural/working-memory interpretations beyond two aggregate runs without per-case rows. The K4 body makes universal scratchpad/architecture and larger-model claims beyond the eight supplied one-fixture traces, and its partial Llama final value is 5 in prose versus 7 in the table. All 90 supplied trace rows have null functional fields and pending admission, and scratchpad/hinted prompts expose target repair values. Modern manuscript corrections appropriately withdraw broad interpretations.',[evidence('docs/source_archive/c005_working_report.md',(1,467)),evidence('docs/source_archive/k4_benchmark_report.md',(1,261)),evidence('docs/source_archive/README.md',(1,30)),evidence('paper_claim_ledger.md',(1,101))],severity='historical_observations_not_general_model_evidence',recommended_action='Preserve working reports as historical assertions with correction notices. Reuse only public finite graph/prompt designs with new independent tasks and checkers; never turn supplied answer-bearing historical prompts into a sealed benchmark.'),
 record('PDF-CLIPPING-AND-KEY-ORDER','The combined companion page 5 (separate study guide page 4) visibly clips long reproduction commands at the right edge. The combined artifact places the worked answer key before the quiz, and preface line 19 directs that order, conflicting with the stated first-attempt-without-key exercise.',[evidence('008_pfp_examiner_companion.pdf',pages=[1,5,7]),evidence('_lev_examiner_theoretical_minimum_quiz/study_guide.pdf',pages=[4]),evidence('_lev_examiner_theoretical_minimum_quiz/00_preface_at_apartment_50.md',(19,21)),evidence('_lev_examiner_theoretical_minimum_quiz/quiz.md',(1,12))],severity='document_usability_and_evaluation_boundary',recommended_action='For a future edition, wrap commands and arrange attempt-before-key navigation. Preserve historical PDF bytes; self-study rubric scores are not validated learning or blinded evaluation.'),
 record('PUBLICATION-METADATA-EDITION-MIX','Metadata combines a description stating no external deposit/DOI with later DOI/record URL notes; rendered PDFs retain historical Landau/repository vocabulary while current prose and receipt paths are renamed. These are edition/context differences, not evidence of a fresh publication or authenticated external record.',[evidence('zenodo_metadata.json',(1,42)),evidence('paper_change_log.md',(1,195)),evidence('docs/descriptions.md',(1,9))],severity='edition_metadata_inconsistency',recommended_action='Maintain a clearly versioned historical release and current adaptation map; externally verify publication status only when a publication task requires it. No external lookup or publication action occurred here.')]
